import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");

        // Input validation - check required params
        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against whitelist
        if (!reportType.matches("^(sales|inventory|payroll|expenses)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date format validation
        if (!startDate.matches("^\\d{4}-\\d{2}-\\d{2}$") ||
            !endDate.matches("^\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Build query - department filter is optional
        String baseQuery = "SELECT id, amount, description, created_at FROM " + reportType +
                          "_reports WHERE created_at BETWEEN '" + startDate + "' AND '" + endDate + "'";

        // Append optional department filter
        if (department != null && !department.isEmpty()) {
            // Basic sanitization - remove obvious dangerous chars
            department = department.replace(";", "").replace("--", "");
            baseQuery += " AND department = '" + department + "'";
        }

        baseQuery += " ORDER BY created_at DESC LIMIT 1000";

        log.info("Executing report query for type=" + reportType + " dates=" + startDate + "/" + endDate);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(baseQuery)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\"results\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"amount\":\"%.2f\",\"desc\":\"%s\",\"date\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getDouble("amount"),
                    rs.getString("description").replace("\"", "\\\""),
                    rs.getString("created_at"));
                first = false;
            }
            out.print("]}");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST not supported for reports
        resp.sendError(405, "Use GET for report queries");
    }
}
